import type { DesignContent } from "@/lib/design-content";

export const content: DesignContent = {"slug": "my-products", "title": "UniShare · My products", "css": "\n:root{--ink:#14201e;--muted:#5b6866;--teal:#0b5b57;--teal-soft:#e3efed;--line:#14201e;--hair:#dfe4e3;--panel:#f4f6f5;--amber-bg:#fdf1d3;--amber-tx:#7a4d00;--white:#fff}\n*{box-sizing:border-box;margin:0;padding:0}\nbody{font-family:\"Schibsted Grotesk\",system-ui,-apple-system,\"Segoe UI\",sans-serif;color:var(--ink);background:var(--white);font-size:14px;line-height:1.45}\na{color:inherit;text-decoration:none}\nbutton,input,select{font:inherit;color:inherit}\nbutton{cursor:pointer}\n:focus-visible{outline:2px solid var(--teal);outline-offset:2px}\n.nav{border-bottom:2px solid var(--line);height:56px;display:flex;align-items:center;justify-content:space-between;padding:0 48px;gap:24px}\n.brand{display:flex;align-items:center;gap:10px;font-weight:700;font-size:20px}\n.brand svg{width:24px;height:24px;color:var(--teal)}\n.nav ul{list-style:none;display:flex;gap:22px;font-size:13px}\n.nav ul a{padding:19px 0;display:block;border-bottom:2px solid transparent;margin-bottom:-2px}\n.nav ul a.on{color:var(--teal);font-weight:600;border-color:var(--teal)}\n.nav-r{display:flex;align-items:center;gap:18px;font-size:13px}\n.nav-r svg.i{width:15px;height:15px}\n.bell{display:flex;align-items:flex-start;gap:2px;color:var(--teal)}\n.bell sup{font-size:8px;font-weight:600;margin-top:2px}\n.sos{display:flex;align-items:center;gap:5px;font-weight:600;color:var(--teal)}\n.user{display:flex;align-items:center;gap:8px}\n.avatar{width:28px;height:28px;border-radius:50%;background:var(--teal-soft);border:1px solid var(--teal);color:var(--teal);font-size:10px;display:grid;place-items:center;font-weight:600}\n.user b{font-weight:600;font-size:12px;line-height:1.2;display:block}\n.user small{display:block;color:var(--muted);font-size:10px;line-height:1.2}\nmain{max-width:824px;margin:0 auto;padding:0 0 48px}\n.crumbs{font-size:11px;color:var(--muted);margin:19px 0 24px;display:flex;gap:6px}\n.head{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;margin-bottom:24px}\n.eyebrow{font-size:9.5px;letter-spacing:.04em;color:var(--teal);font-weight:600;text-transform:uppercase;margin-bottom:10px}\nh1{font-size:34px;line-height:1.1;font-weight:800;letter-spacing:-.01em;margin-bottom:10px}\n.lede{color:var(--muted);font-size:13px}\n.btn{border:1.5px solid var(--teal);color:var(--teal);background:#fff;border-radius:8px;padding:8px 12px;font-weight:600;font-size:11px;white-space:nowrap;display:inline-flex;align-items:center;justify-content:center;gap:8px}\n.btn:hover{background:var(--teal-soft)}\n.btn.solid{background:var(--teal);color:#fff;font-size:12.5px;padding:12px 18px}\n.btn.solid:hover{background:#094a47}\n.head .btn{margin-top:18px}\n.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:30px}\n.stat{border:1.5px solid var(--line);border-radius:12px;padding:16px 16px 14px;min-height:118px;display:flex;flex-direction:column}\n.stat small{font-size:10.5px;color:var(--muted)}\n.stat b{font-size:24px;font-weight:800;margin:14px 0;line-height:1.1;letter-spacing:-.01em}\n.stat span{font-size:10px;color:var(--muted);margin-top:auto}\n.tabs{display:flex;gap:24px;border-bottom:2px solid var(--teal-soft);margin-bottom:22px;font-size:12px}\n.tabs button{background:none;border:0;border-bottom:2px solid transparent;margin-bottom:-2px;padding:8px 0 12px}\n.tabs button.on{color:var(--teal);font-weight:700;border-color:var(--teal)}\n.bar{display:flex;gap:10px;margin-bottom:20px}\n.search{flex:1;display:flex;align-items:center;gap:10px;border:1px solid var(--hair);border-radius:8px;padding:0 14px;height:35px;min-width:0}\n.search svg{width:12px;height:12px;color:var(--teal);flex:none}\n.search input{flex:1;border:0;outline:0;background:transparent;font-size:11.5px;min-width:0}\n.search:focus-within{outline:2px solid var(--teal);outline-offset:2px}\n.fb{display:inline-flex;align-items:center;gap:8px;border:1.5px solid var(--teal);color:var(--teal);background:#fff;border-radius:8px;padding:0 12px;height:35px;font-weight:600;font-size:11.5px}\n.fb svg{width:12px;height:12px;flex:none}\n.fb select{appearance:none;-webkit-appearance:none;border:0;background:transparent;color:var(--teal);font-weight:600;font-size:11.5px;outline:0;cursor:pointer}\n.table{border:1.5px solid var(--line);border-radius:12px;overflow:hidden;margin-bottom:20px}\n.thead,.prow{display:grid;grid-template-columns:1.9fr 1fr 1fr .9fr;gap:12px;padding:0 15px}\n.thead{background:var(--panel);font-size:9.5px;letter-spacing:.03em;color:var(--muted);text-transform:uppercase;padding-top:14px;padding-bottom:14px;font-weight:600}\n.rows{list-style:none}\n.prow{padding-top:16px;padding-bottom:16px;border-bottom:1px solid var(--hair);align-items:center}\n.prow:last-child{border-bottom:0}\n.prod{display:flex;gap:14px;align-items:center}\n.prod img{width:93px;height:82px;object-fit:cover;border-radius:6px;flex:none;display:block;background:var(--panel)}\n.prod small{font-size:9.5px;color:var(--muted)}\n.prod h3{font-size:13.5px;font-weight:700;margin:4px 0 6px;line-height:1.25}\n.prod p{font-size:9.5px;color:var(--muted);line-height:1.5}\n.price b{display:block;font-size:11px;color:var(--teal);font-weight:700;margin-bottom:4px}\n.price span{display:block;font-size:10px;color:var(--muted);margin-bottom:4px}\n.price a,.avail a{font-size:9.5px;font-weight:700;color:var(--teal)}\n.price a:hover,.avail a:hover{text-decoration:underline}\n.badge{display:inline-block;font-size:9px;font-weight:700;border-radius:999px;padding:4px 10px;margin-bottom:8px}\n.b-active{background:var(--teal-soft);color:var(--teal)}\n.b-rentedout{background:var(--amber-bg);color:var(--amber-tx)}\n.b-paused,.b-draft{background:#eceeed;color:#3a4745}\n.avail .av{display:block;font-size:10px;color:var(--muted);margin-bottom:6px}\n.manage{display:flex;flex-direction:column;gap:8px;align-items:flex-end}\n.manage .btn{min-width:80px}\n.empty{display:none;padding:34px 16px;text-align:center;color:var(--muted);font-size:12.5px}\n.empty b{display:block;color:var(--ink);font-size:15px;margin-bottom:4px}\n.notice{background:var(--teal-soft);border-radius:8px;padding:15px 20px;display:flex;gap:12px}\n.notice svg{width:16px;height:16px;color:var(--teal);flex:none;margin-top:2px}\n.notice b{display:block;color:var(--teal);font-size:11.5px;margin-bottom:2px}\n.notice span{font-size:10.5px;color:var(--muted)}\nfooter{border-top:2px solid var(--line);padding:22px 48px 26px;display:flex;justify-content:space-between;font-size:11.5px;color:var(--muted)}\nfooter nav{display:flex;gap:22px}\nfooter nav a{color:var(--teal);font-weight:600}\n@media (max-width:1040px){.nav ul{display:none}}\n@media (max-width:860px){.stats{grid-template-columns:repeat(2,1fr)}}\n@media (max-width:760px){\n  main{padding:0 20px 40px}\n  .nav,footer{padding-left:20px;padding-right:20px}\n  .head{flex-direction:column;gap:0}\n  .tabs{overflow-x:auto;white-space:nowrap}\n  .bar{flex-wrap:wrap}.search{flex-basis:100%}\n  .thead{display:none}\n  .prow{grid-template-columns:1fr;gap:14px}\n  .manage{flex-direction:row;justify-content:flex-start}\n  footer{flex-direction:column;gap:10px}\n}\n", "body": "\n<header class=\"nav\">\n  <a class=\"brand\" href=\"/\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\"><circle cx=\"7\" cy=\"12\" r=\"4\"/><circle cx=\"17\" cy=\"12\" r=\"4\"/></svg>UniShare</a>\n  <ul>\n    <li><a href=\"/campus-home\">Home</a></li><li><a href=\"/marketplace\">Marketplace</a></li><li><a class=\"on\" href=\"/my-products\">My products</a></li><li><a href=\"/my-rentals\">My rentals</a></li><li><a href=\"/ride-home-and-search\">Rides</a></li><li><a href=\"/wallet-overview\">Wallet</a></li><li><a href=\"/favorites\">Favorites</a></li>\n  </ul>\n  <div class=\"nav-r\">\n    <span class=\"bell\" aria-label=\"3 notifications\"><svg class=\"i\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M6 17V11a6 6 0 0 1 12 0v6l1.5 2h-15zM10 21h4\"/></svg><sup>3</sup></span>\n    <a class=\"sos\" href=\"/student-sos-assistance\"><svg class=\"i\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"><path d=\"M12 3l8 3v6c0 5-3.5 8-8 9-4.5-1-8-4-8-9V6z\"/><path d=\"M9 12l2 2 4-4\" stroke-linecap=\"round\"/></svg>SOS</a>\n    <div class=\"user\"><span class=\"avatar\">FR</span><div><b>Farhana Rahman</b><small>My profile</small></div></div>\n  </div>\n</header>\n\n<main>\n  <nav class=\"crumbs\" aria-label=\"Breadcrumb\"><a href=\"/campus-home\">Home</a><span>›</span><span>My products</span></nav>\n  <div class=\"head\">\n    <div>\n      <div class=\"eyebrow\">University of Dhaka · Verified students only</div>\n      <h1>My products</h1>\n      <p class=\"lede\">Your shared shelf. Manage listings, prices and the days you can lend.</p>\n    </div>\n    <a class=\"btn solid\" href=\"/add-product\"><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.6\" stroke-linecap=\"round\"><path d=\"M12 5v14M5 12h14\"/></svg>Add product</a>\n  </div>\n\n  <section class=\"stats\" aria-label=\"Summary\">\n    <div class=\"stat\"><small>Total products</small><b id=\"sTotal\">4</b><span>All owned by you</span></div>\n    <div class=\"stat\"><small>Live listings</small><b id=\"sLive\">2</b><span>1 available · 1 rented out</span></div>\n    <div class=\"stat\"><small>Paused &amp; drafts</small><b id=\"sOff\">2</b><span id=\"sOffTxt\">1 paused · 1 draft</span></div>\n    <div class=\"stat\"><small>Rental earnings</small><b>360 tokens</b><span>This month</span></div>\n  </section>\n\n  <div class=\"tabs\" id=\"tabs\" role=\"tablist\">\n    <button class=\"on\" role=\"tab\" data-f=\"all\" type=\"button\" id=\"tAll\">All products (4)</button>\n    <button role=\"tab\" data-f=\"active\" type=\"button\" id=\"tActive\">Active (2)</button>\n    <button role=\"tab\" data-f=\"paused\" type=\"button\" id=\"tPaused\">Paused (1)</button>\n    <button role=\"tab\" data-f=\"draft\" type=\"button\" id=\"tDraft\">Drafts (1)</button>\n  </div>\n\n  <div class=\"bar\">\n    <label class=\"search\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.6\"><circle cx=\"12\" cy=\"12\" r=\"6\"/></svg><input id=\"q\" type=\"search\" placeholder=\"Search your products\" aria-label=\"Search your products\"></label>\n    <label class=\"fb\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M6 9l6 6 6-6\"/></svg><select id=\"cat\" aria-label=\"Category\"><option value=\"all\">All categories</option><option>Cameras</option><option>Study essentials</option><option>Camera accessories</option><option>Travel essentials</option></select></label>\n    <label class=\"fb\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M6 9l6 6 6-6\"/></svg><select id=\"sort\" aria-label=\"Sort\"><option value=\"recent\">Sort: Recently updated</option><option value=\"low\">Sort: Price, low to high</option><option value=\"high\">Sort: Price, high to low</option></select></label>\n  </div>\n\n  <section class=\"table\" aria-label=\"Products\">\n    <div class=\"thead\"><span>Product / Condition</span><span>Token pricing</span><span>Availability</span><span style=\"text-align:left\">Manage</span></div>\n    <ul class=\"rows\" id=\"rows\">\n      <li class=\"prow\" data-state=\"active\" data-name=\"canon eos 200d\" data-cat=\"Cameras\" data-i=\"0\" data-rate=\"60\">\n        <div class=\"c prod\"><img src=\"data:image/jpeg;base64,\" alt=\"Canon EOS 200D\"><div><small>Cameras · Good</small><h3>Canon EOS 200D</h3><p>Owner: Farhana Rahman · You</p><p class=\"note\">Booked 16–18 Oct · 1 pending request</p></div></div>\n        <div class=\"c price\"><b>60 tokens / day</b><span>300 tokens deposit</span><a href=\"/edit-product\">Edit pricing →</a></div>\n        <div class=\"c avail\"><span class=\"badge b-active\">Active</span><span class=\"av\">Available today</span><a href=\"/product-availability\">Manage dates →</a></div>\n        <div class=\"c manage\"></div>\n      </li>\n      <li class=\"prow\" data-state=\"active\" data-name=\"adjustable study lamp\" data-cat=\"Study essentials\" data-i=\"1\" data-rate=\"20\">\n        <div class=\"c prod\"><img src=\"data:image/jpeg;base64,\" alt=\"Adjustable study lamp\"><div><small>Study essentials · Good</small><h3>Adjustable study lamp</h3><p>Owner: Farhana Rahman · You</p><p class=\"note\">With Nabila Sultana · Return 16 Oct</p></div></div>\n        <div class=\"c price\"><b>20 tokens / day</b><span>80 tokens deposit</span><a href=\"/edit-product\">Edit pricing →</a></div>\n        <div class=\"c avail\"><span class=\"badge b-rentedout\">Rented out</span><span class=\"av\">Available 17 Oct</span><a href=\"/product-availability\">Manage dates →</a></div>\n        <div class=\"c manage\"></div>\n      </li>\n      <li class=\"prow\" data-state=\"paused\" data-name=\"compact camera tripod\" data-cat=\"Camera accessories\" data-i=\"2\" data-rate=\"25\">\n        <div class=\"c prod\"><img src=\"data:image/jpeg;base64,\" alt=\"Compact camera tripod\"><div><small>Camera accessories · Good</small><h3>Compact camera tripod</h3><p>Owner: Farhana Rahman · You</p><p class=\"note\">Paused by you on 11 Oct</p></div></div>\n        <div class=\"c price\"><b>25 tokens / day</b><span>100 tokens deposit</span><a href=\"/edit-product\">Edit pricing →</a></div>\n        <div class=\"c avail\"><span class=\"badge b-paused\">Paused</span><span class=\"av\">Not accepting bookings</span><a href=\"/product-availability\">Manage dates →</a></div>\n        <div class=\"c manage\"></div>\n      </li>\n      <li class=\"prow\" data-state=\"draft\" data-name=\"weekend hiking backpack\" data-cat=\"Travel essentials\" data-i=\"3\" data-rate=\"30\">\n        <div class=\"c prod\"><img src=\"data:image/jpeg;base64,\" alt=\"Weekend hiking backpack\"><div><small>Travel essentials · Like new</small><h3>Weekend hiking backpack</h3><p>Owner: Farhana Rahman · You</p><p class=\"note\">Add availability to finish your listing</p></div></div>\n        <div class=\"c price\"><b>30 tokens / day</b><span>100 tokens deposit</span><a href=\"/edit-product\">Edit pricing →</a></div>\n        <div class=\"c avail\"><span class=\"badge b-draft\">Draft</span><span class=\"av\">Not published</span><a href=\"/product-availability\">Manage dates →</a></div>\n        <div class=\"c manage\"></div>\n      </li>\n    </ul>\n    <div class=\"empty\" id=\"empty\"><b>No products here</b>Try another filter or add a new product.</div>\n  </section>\n\n  <div class=\"notice\" role=\"note\">\n    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 3l8 3v6c0 5-3.5 8-8 9-4.5-1-8-4-8-9V6z\"/><path d=\"M9 12l2 2 4-4\"/></svg>\n    <div><b>Your listings are visible only to verified DU students.</b><span>Keep condition, photos and availability up to date. Pausing stops new requests without cancelling confirmed rentals.</span></div>\n  </div>\n</main>\n\n<footer>\n  <span>UniShare. Made for university students in Bangladesh.</span>\n  <nav><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/get-help\">Get help</a><a href=\"/\">Log out</a></nav>\n</footer>\n\n\n", "scripts": ["\n(function(){\n  var rows=document.getElementById('rows'),tabs=document.getElementById('tabs'),q=document.getElementById('q'),cat=document.getElementById('cat'),sort=document.getElementById('sort'),empty=document.getElementById('empty');\n  var all=Array.prototype.slice.call(rows.children),f='all';\n  function btn(txt,cls,act){var b=document.createElement('button');b.type='button';b.className='btn';b.textContent=txt;b.dataset.act=act;return b}\n  function buildManage(r){\n    var m=r.querySelector('.manage');m.innerHTML='';\n    var s=r.dataset.state;\n    if(s==='draft'){m.appendChild(btn('Finish draft','','finish'));m.appendChild(btn('Delete draft','','delete'))}\n    else{m.appendChild(btn('Edit product','','edit'));m.appendChild(btn(s==='paused'?'Resume':'Pause listing','',s==='paused'?'resume':'pause'))}\n  }\n  function setState(r,s){\n    r.dataset.state=s;\n    var b=r.querySelector('.badge'),av=r.querySelector('.av');\n    if(s==='paused'){b.className='badge b-paused';b.textContent='Paused';av.textContent='Not accepting bookings';r.querySelector('.note').textContent='Paused by you today'}\n    else if(s==='active'){b.className='badge b-active';b.textContent='Active';av.textContent='Available today';r.querySelector('.note').textContent='Resumed by you today'}\n    buildManage(r);\n  }\n  function counts(){\n    var c={active:0,paused:0,draft:0};\n    all.forEach(function(r){if(r.isConnected)c[r.dataset.state]++});\n    var tot=c.active+c.paused+c.draft;\n    document.getElementById('tAll').textContent='All products ('+tot+')';\n    document.getElementById('tActive').textContent='Active ('+c.active+')';\n    document.getElementById('tPaused').textContent='Paused ('+c.paused+')';\n    document.getElementById('tDraft').textContent='Drafts ('+c.draft+')';\n    document.getElementById('sTotal').textContent=tot;\n    document.getElementById('sLive').textContent=c.active;\n    document.getElementById('sOff').textContent=c.paused+c.draft;\n    document.getElementById('sOffTxt').textContent=c.paused+' paused · '+c.draft+(c.draft===1?' draft':' drafts');\n  }\n  function render(){\n    var term=q.value.trim().toLowerCase(),shown=0;\n    var list=all.filter(function(r){return r.isConnected}).sort(function(a,b){\n      return sort.value==='low'?a.dataset.rate-b.dataset.rate:sort.value==='high'?b.dataset.rate-a.dataset.rate:a.dataset.i-b.dataset.i});\n    list.forEach(function(r){\n      rows.appendChild(r);\n      var ok=(f==='all'||r.dataset.state===f)&&(!term||r.dataset.name.indexOf(term)>-1)&&(cat.value==='all'||r.dataset.cat===cat.value);\n      r.style.display=ok?'':'none';if(ok)shown++;\n    });\n    empty.style.display=shown?'none':'block';\n    counts();\n  }\n  all.forEach(buildManage);\n  rows.addEventListener('click',function(e){\n    var b=e.target.closest('button[data-act]');if(!b)return;\n    var r=b.closest('.prow'),a=b.dataset.act;\n    if(a==='pause')setState(r,'paused');\n    else if(a==='resume')setState(r,'active');\n    else if(a==='delete'){if(confirm('Delete this draft?'))r.remove()}\n    render();\n  });\n  tabs.addEventListener('click',function(e){\n    var b=e.target.closest('button');if(!b)return;\n    Array.prototype.forEach.call(tabs.children,function(x){x.classList.remove('on')});\n    b.classList.add('on');f=b.dataset.f;render();\n  });\n  q.addEventListener('input',render);cat.addEventListener('change',render);sort.addEventListener('change',render);\n  render();\n})();\n"], "fonts": ["https://fonts.googleapis.com/css2?family=Schibsted+Grotesk:wght@400;500;600;700;800&display=swap"]};

